"use client";

import { useMemo, useState } from "react";
import { zodResolver } from "@hookform/resolvers/zod";
import { Controller, useForm } from "react-hook-form";
import { z } from "zod";
import { Copy, FileText, Pencil, Plus, Search } from "lucide-react";
import { toast } from "sonner";
import type { MessageTemplate } from "@/types/chatbot";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { templateFormSchema } from "@/services/chatbot/schemas";

interface Props { templates: MessageTemplate[]; isBusy: boolean; onSave: (template: MessageTemplate) => Promise<void> }

export function TemplatesWorkspace({ templates, isBusy, onSave }: Props) {
  const [search, setSearch] = useState(""); const [category, setCategory] = useState("all"); const [editing, setEditing] = useState<MessageTemplate | null>(null); const [creating, setCreating] = useState(false);
  const active = editing ?? (creating ? emptyTemplate(templates.length + 1) : null);
  const visible = useMemo(() => templates.filter((item) => (category === "all" || item.category === category) && item.name.toLowerCase().includes(search.toLowerCase())), [templates, search, category]);
  async function duplicate(template: MessageTemplate) { try { await onSave({ ...template, id: `${template.id}-copy-${templates.length}`, name: `${template.name.slice(0, 110)} — cópia`, status: "draft", updatedAt: new Date().toISOString() }); toast.success("Cópia criada como rascunho"); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível duplicar o template."); } }
  async function toggle(template: MessageTemplate) { try { await onSave({ ...template, status: template.status === "active" ? "inactive" : "active", updatedAt: new Date().toISOString() }); toast.success(template.status === "active" ? "Template desativado" : "Template ativado na simulação"); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível alterar o template."); } }
  return <div className="space-y-4 p-4 md:p-5" data-testid="chatbot-templates"><header className="flex items-center justify-between"><div><h2 className="text-lg font-semibold text-white">Templates</h2><p className="text-sm text-slate-400">Mensagens reutilizáveis por categoria e canal.</p></div><Button disabled={isBusy} onClick={() => setCreating(true)}><Plus className="mr-2 size-4" />Novo template</Button></header>
    <div className="flex flex-col gap-2 sm:flex-row"><label className="relative flex-1"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-500" /><Input value={search} onChange={(e) => setSearch(e.target.value)} aria-label="Pesquisar templates" placeholder="Pesquisar templates" className="border-white/10 bg-slate-950/60 pl-9 text-white" /></label><Select value={category} onValueChange={setCategory}><SelectTrigger className="border-white/10 bg-slate-950/60 text-white sm:w-44"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">Todas categorias</SelectItem><SelectItem value="marketing">Marketing</SelectItem><SelectItem value="utility">Utilidade</SelectItem><SelectItem value="support">Suporte</SelectItem></SelectContent></Select></div>
    <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{visible.map((template) => <article key={template.id} className="flex min-h-64 flex-col rounded-xl border border-white/10 bg-slate-950/60 p-4"><header className="flex items-start justify-between gap-2"><div className="flex gap-3"><div className="grid size-9 place-items-center rounded-lg bg-indigo-400/10 text-indigo-300"><FileText className="size-4" /></div><div><h3 className="font-medium text-white">{template.name}</h3><p className="text-xs capitalize text-slate-500">{template.channel} · {template.language}</p></div></div><Badge className={template.status === "active" ? "bg-emerald-400/10 text-emerald-300" : "bg-slate-700 text-slate-300"}>{template.status}</Badge></header><div className="my-4 flex-1 rounded-lg border border-white/5 bg-white/[0.025] p-3 text-sm leading-6 text-slate-300">{template.content}</div><footer className="flex items-center justify-between"><Badge variant="outline" className="capitalize text-slate-400">{template.category}</Badge><div className="flex gap-1"><Button variant="ghost" size="sm" disabled={isBusy} onClick={() => { void toggle(template); }}>{template.status === "active" ? "Desativar" : "Ativar"}</Button><Button variant="ghost" size="icon" disabled={isBusy} onClick={() => { void duplicate(template); }} aria-label={`Duplicar ${template.name}`}><Copy className="size-4" /></Button><Button variant="ghost" size="icon" disabled={isBusy} onClick={() => setEditing(template)} aria-label={`Editar ${template.name}`}><Pencil className="size-4" /></Button></div></footer></article>)}</div>
    {!visible.length && <div className="rounded-xl border border-dashed border-white/10 py-16 text-center text-sm text-slate-500">Nenhum template corresponde aos filtros.</div>}
    <Dialog open={Boolean(active)} onOpenChange={(open) => { if (!open && !isBusy) { setEditing(null); setCreating(false); } }}><DialogContent className="border-white/10 bg-slate-950 text-white"><DialogHeader><DialogTitle>{creating ? "Novo template" : "Editar template"}</DialogTitle><DialogDescription className="text-slate-400">Use variáveis como {"{{nome}}"}; nenhuma mensagem será enviada.</DialogDescription></DialogHeader>{active && <TemplateFormPanel template={active} isBusy={isBusy} onSave={async (template) => { await onSave(template); toast.success("Template salvo no ambiente mock"); setEditing(null); setCreating(false); }} />}</DialogContent></Dialog>
  </div>;
}
function emptyTemplate(number: number): MessageTemplate { return { id: `template-new-${number}`, name: "", category: "utility", channel: "whatsapp", content: "", status: "draft", language: "pt-BR", updatedAt: new Date().toISOString() }; }
type TemplateForm = z.infer<typeof templateFormSchema>;
function TemplateFormPanel({ template, isBusy, onSave }: { template: MessageTemplate; isBusy: boolean; onSave: (template: MessageTemplate) => Promise<void> }) { const { register, control, handleSubmit, formState: { errors } } = useForm<TemplateForm>({ resolver: zodResolver(templateFormSchema), defaultValues: { name: template.name, category: template.category, channel: template.channel, content: template.content, language: template.language } }); return <form onSubmit={handleSubmit(async (values) => { try { await onSave({ ...template, ...values, updatedAt: new Date().toISOString() }); } catch (error) { toast.error(error instanceof Error ? error.message : "Não foi possível salvar o template."); } })} aria-busy={isBusy} className="space-y-3"><Field error={errors.name?.message}><Input {...register("name")} disabled={isBusy} maxLength={120} placeholder="Nome" aria-invalid={Boolean(errors.name)} /></Field><div className="grid grid-cols-3 gap-2"><Controller name="category" control={control} render={({ field }) => <Picker value={field.value} onChange={field.onChange} disabled={isBusy} invalid={Boolean(errors.category)} options={["marketing", "utility", "support"]} />} /><Controller name="channel" control={control} render={({ field }) => <Picker value={field.value} onChange={field.onChange} disabled={isBusy} invalid={Boolean(errors.channel)} options={["whatsapp", "instagram", "messenger", "telegram", "email", "webchat"]} />} /><Input {...register("language")} disabled={isBusy} maxLength={20} aria-label="Idioma" aria-invalid={Boolean(errors.language)} /></div>{(errors.category || errors.channel || errors.language) && <p role="alert" className="text-xs text-rose-300">{errors.category?.message ?? errors.channel?.message ?? errors.language?.message}</p>}<Field error={errors.content?.message}><textarea {...register("content")} disabled={isBusy} maxLength={10000} placeholder="Conteúdo da mensagem" aria-invalid={Boolean(errors.content)} className="min-h-36 w-full rounded-md border border-white/10 bg-slate-900 p-3 text-sm outline-none focus:ring-2 focus:ring-indigo-400" /></Field><Button type="submit" disabled={isBusy} className="w-full">{isBusy ? "Salvando…" : "Salvar template"}</Button></form>; }
function Picker({ value, onChange, options, disabled, invalid }: { value: string; onChange: (value: string) => void; options: string[]; disabled: boolean; invalid: boolean }) { return <Select value={value} onValueChange={onChange} disabled={disabled}><SelectTrigger aria-invalid={invalid} className="border-white/10 bg-slate-900"><SelectValue /></SelectTrigger><SelectContent>{options.map((option) => <SelectItem key={option} value={option}>{option}</SelectItem>)}</SelectContent></Select>; }
function Field({ error, children }: { error?: string; children: React.ReactNode }) { return <label className="block">{children}{error && <span role="alert" className="mt-1 block text-xs text-rose-300">{error}</span>}</label>; }
